class Solution {
    using Poly = map<vector<string>, int>;
    vector<string> tokens;
    int pos = 0;
    unordered_map<string, int> vals;

    Poly add(Poly a, const Poly& b, int sign = 1) {
        for (auto& [term, coef] : b) {
            a[term] += sign * coef;
            if (a[term] == 0) a.erase(term);
        }
        return a;
    }

    Poly mul(const Poly& a, const Poly& b) {
        Poly res;
        for (auto& [ta, ca] : a) for (auto& [tb, cb] : b) {
            vector<string> term = ta;
            term.insert(term.end(), tb.begin(), tb.end());
            sort(term.begin(), term.end());
            res[term] += ca * cb;
            if (res[term] == 0) res.erase(term);
        }
        return res;
    }

    Poly atom() {
        string t = tokens[pos++];
        if (t == "(") {
            Poly res = expr();
            pos++;
            return res;
        }
        if (isdigit(t[0]) || t[0] == '-') return {{{}, stoi(t)}};
        if (vals.count(t)) return {{{}, vals[t]}};
        return {{{t}, 1}};
    }

    Poly term() {
        Poly res = atom();
        while (pos < tokens.size() && tokens[pos] == "*") {
            pos++;
            res = mul(res, atom());
        }
        return res;
    }

    Poly expr() {
        Poly res = term();
        while (pos < tokens.size() && tokens[pos] != ")") {
            string op = tokens[pos++];
            res = add(res, term(), op == "+" ? 1 : -1);
        }
        return res;
    }

public:
    vector<string> basicCalculatorIV(string expression, vector<string>& evalvars, vector<int>& evalints) {
        for (int i = 0; i < evalvars.size(); i++) vals[evalvars[i]] = evalints[i];
        for (int i = 0; i < expression.size();) {
            if (expression[i] == ' ') { i++; continue; }
            if (string("()+-*").find(expression[i]) != string::npos) tokens.push_back(string(1, expression[i++]));
            else {
                int j = i;
                while (j < expression.size() && expression[j] != ' ' && string("()+-* ").find(expression[j]) == string::npos) j++;
                tokens.push_back(expression.substr(i, j - i));
                i = j;
            }
        }
        Poly p = expr();
        vector<pair<vector<string>, int>> items;
        for (auto& [term, coef] : p) if (coef) items.push_back({term, coef});
        sort(items.begin(), items.end(), [](auto& a, auto& b) {
            if (a.first.size() != b.first.size()) return a.first.size() > b.first.size();
            return a.first < b.first;
        });
        vector<string> ans;
        for (auto& [term, coef] : items) {
            string cur = to_string(coef);
            for (auto& v : term) cur += "*" + v;
            ans.push_back(cur);
        }
        return ans;
    }
};
